#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXN 1005

int N;
char target[MAXN];

void add_one(char *num, int *len) {
    int carry = 1;
    for (int i = *len - 1; i >= 0 && carry; i--) {
        int sum = (num[i] - '0') + carry;
        num[i] = (sum % 10) + '0';
        carry = sum / 10;
    }
    if (carry) {
        memmove(num + 1, num, *len + 1);
        num[0] = '1';
        (*len)++;
    }
}

bool check(int L) {
    char current[MAXN];
    memcpy(current, target, L);
    current[L] = '\0';
    int cur_len = L;

    int idx = L;
    while (idx < N) {
        add_one(current, &cur_len);
        if (idx + cur_len > N) {
            return false;
        }
        for (int i = 0; i < cur_len; i++) {
            if (current[i] != target[idx + i]) {
                return false;
            }
        }
        idx += cur_len;
    }

    return idx == N;
}

int main() {
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 0; i < N; i++) {
        int d;
        scanf("%d", &d);
        target[i] = d + '0';
    }
    target[N] = '\0';

    for (int L = 1; L <= N; L++) {
        if (check(L)) {
            for (int i = 0; i < L; i++) {
                putchar(target[i]);
            }
            putchar('\n');
            break;
        }
    }

    return 0;
}
